    BOOK_CACHE = None

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        MyPlayer._pattern_bit_specs()
        MyPlayer._precompute_evaluation_tables()

    def next_move(self, board: Board) -> Move:
        start_time = time.perf_counter()
        self._profile_stats = {}
        self._eval_count = 0
        self._legal_moves_count = 0
        self._legal_moves_total_sec = 0.0
        self._legal_moves_cache_hits = 0
        self._legal_moves_cache_misses = 0
        self._eval_cache_hits = 0
        self._eval_cache_misses = 0
        self._pattern_bit_specs()
        type(self).SEARCH_HASH_GET_COUNT = 0
        type(self).SEARCH_HASH_REG_COUNT = 0
        move_no = self._move_number(board)
        state = self._board_to_bits(board)
        moves = self._legal_moves_bits(state, self.color)
        if not moves:
            elapsed_ms = (time.perf_counter() - start_time) * 1000
            self._write_time_log(move_no, elapsed_ms, None, "pass")
            self._print_legal_moves_profile(move_no)
            self._print_hotspot_profile(move_no, elapsed_ms / 1000.0)
            return None

        book_move = self._book_move_bits(state)
        if book_move is not None and self._move_to_pos(book_move) in moves:
            elapsed_ms = (time.perf_counter() - start_time) * 1000
            self._write_time_log(move_no, elapsed_ms, book_move, "book")
            self._print_legal_moves_profile(move_no)
            self._print_hotspot_profile(move_no, elapsed_ms / 1000.0)
            return book_move

        best_move = moves[0]
        best_score = float("-inf")
        alpha = float("-inf")
        beta = float("inf")

        if self._empty_count_bits(state) <= self.ENDGAME_EXACT_EMPTY:
            moves = self._order_moves_by_opponent_mobility(state, moves, self.color)
            for move in moves:
                next_state = self._apply_move_bits(state, move, self.color)
                endgame_start = self._profile_start()
                score = -self._endgame_exact_search(
                    next_state,
                    self._opponent_of(self.color),
                    -65,
                    65,
                )
                self._profile_add("endgame_exact_root", endgame_start)
                if score > best_score:
                    best_score = score
                    best_move = move
                alpha = max(alpha, best_score)

            elapsed_ms = (time.perf_counter() - start_time) * 1000
            result = self._pos_to_move(best_move)
            self._write_time_log(move_no, elapsed_ms, result, "endgame_exact")
            self._print_legal_moves_profile(move_no)
            self._print_hotspot_profile(move_no, elapsed_ms / 1000.0)
            return result

        moves = self._order_move_positions_by_weight(moves)
        for move in moves:
            next_state = self._apply_move_bits(state, move, self.color)
            score = -self._negascout(
                next_state,
                depth=self.SEARCH_DEPTH - 1,
                current_color=self._opponent_of(self.color),
                alpha=-beta,
                beta=-alpha,
            )
            if score > best_score:
                best_score = score
                best_move = move
            alpha = max(alpha, best_score)

        elapsed_ms = (time.perf_counter() - start_time) * 1000
        result = self._pos_to_move(best_move)
        self._write_time_log(move_no, elapsed_ms, result, "search")
        self._print_legal_moves_profile(move_no)
        self._print_hotspot_profile(move_no, elapsed_ms / 1000.0)
        return result

    def _move_number(self, board: Board) -> int:
        stones = 0
        for row in board:
            for cell in row:
                if cell != Cell.EMPTY:
                    stones += 1
        return stones - 3

    def _log_file_name(self, suffix: str) -> str:
        try:
            player_file = os.environ.get("MYPLAYER_FILE", "")
        except NameError:
            player_file = ""
        player_path = player_file.replace("\\", "/")
        stem = player_path.split("/")[-1].removesuffix(".py")
        if not stem:
            stem = "current"
        if "/baselines/" in player_path:
            log_dir = "profiles/baselines"
        elif "/experiments/" in player_path:
            log_dir = "profiles/experiments"
        elif stem == "current":
            log_dir = "profiles/current"
        else:
            log_dir = "profiles"
        os.makedirs(log_dir, exist_ok=True)
        return f"{log_dir}/{stem}_{suffix}.txt"

    def _write_time_log(self, move_no: int, elapsed_ms: float, move: Move, source: str):
        return None

    def _timed_legal_moves_bits(self, state: tuple[int, int], color: Cell) -> tuple[int, ...]:
        start_time = time.perf_counter()
        moves = self._legal_moves_bits_uncached(state, color)
        elapsed = time.perf_counter() - start_time
        self._legal_moves_count += 1
        self._legal_moves_total_sec += elapsed
        total_sec, count = self._profile_stats.get("legal_moves_uncached", (0.0, 0))
        self._profile_stats["legal_moves_uncached"] = (total_sec + elapsed, count + 1)
        return tuple(moves)

    def _print_legal_moves_profile(self, move_no: int) -> None:
        count = self._legal_moves_count
        total_sec = self._legal_moves_total_sec
        avg_sec = total_sec / count if count else 0.0
        print(
            f"[legal_moves_bits] move_no={move_no} "
            f"calls={count} total_sec={total_sec:.6f} avg_sec={avg_sec:.6f} "
            f"legal_cache_hits={self._legal_moves_cache_hits} "
            f"legal_cache_misses={self._legal_moves_cache_misses}",
            flush=True,
        )

    def _profile_start(self) -> float:
        return time.perf_counter()

    def _profile_add(self, name: str, start_time: float) -> None:
        total_sec, count = self._profile_stats.get(name, (0.0, 0))
        self._profile_stats[name] = (total_sec + time.perf_counter() - start_time, count + 1)

    def _print_hotspot_profile(self, move_no: int, total_sec: float) -> None:
        print(f"[hotspots] move_no={move_no} total_sec={total_sec:.6f}", flush=True)
        print(
            f"  eval_cache: hits={self._eval_cache_hits} "
            f"misses={self._eval_cache_misses} "
            f"size={len(type(self).EVAL_CACHE)}",
            flush=True,
        )
        for name, (sec, count) in sorted(
            self._profile_stats.items(),
            key=lambda item: item[1][0],
            reverse=True,
        )[:14]:
            avg = sec / count if count else 0.0
            pct = (sec / total_sec * 100.0) if total_sec else 0.0
            print(
                f"  {name}: calls={count} total_sec={sec:.6f} "
                f"avg_sec={avg:.6f} pct={pct:.1f}%",
                flush=True,
            )

    def _order_move_positions_by_weight(self, moves: tuple[int, ...] | list[int]) -> list[int]:
        return sorted(moves, key=lambda pos: self.ORDER_WEIGHTS[pos // 8][pos % 8], reverse=True)

    def _order_moves_by_opponent_mobility(
        self,
        state: tuple[int, int],
        moves: tuple[int, ...] | list[int],
        current_color: Cell,
    ) -> list[int]:
        next_color = self._opponent_of(current_color)
        return sorted(
            moves,
            key=lambda move: self._legal_move_mask_bits(
                self._apply_move_bits(state, move, current_color),
                next_color,
            ).bit_count(),
        )

    def _endgame_exact_search(
        self,
        state: tuple[int, int],
        current_color: Cell,
        alpha: int,
        beta: int,
    ) -> int:
        moves = self._legal_moves_bits(state, current_color)
        next_color = self._opponent_of(current_color)

        if not moves:
            if not self._legal_moves_bits(state, next_color):
                return self._terminal_score_for_color_bits(state, current_color)
            return -self._endgame_exact_search(state, next_color, -beta, -alpha)

        best_score = -65
        moves = self._order_moves_by_opponent_mobility(state, moves, current_color)
        for move in moves:
            next_state = self._apply_move_bits(state, move, current_color)
            score = -self._endgame_exact_search(next_state, next_color, -beta, -alpha)
            if score > best_score:
                best_score = score
            if score > alpha:
                alpha = score
            if alpha >= beta:
                break

        return best_score

    def _negascout(
        self,
        state: tuple[int, int],
        depth: int,
        current_color: Cell,
        alpha: float,
        beta: float,
        allow_probcut: bool = True,
    ) -> float:
        # 葉ノードでは、現在手番から見た盤面評価を返す。
        if depth == 0:
            return self._evaluate_for_color_bits(state, current_color)

        original_alpha = alpha
        original_beta = beta
        search_key = self._search_hash_key(state, depth, current_color, allow_probcut)
        cached = self._search_hash_get(search_key, alpha, beta)
        if cached is not None:
            return cached

        # 葉に近い浅い探索では、NegaScoutではなく通常のalpha-betaを使う。
        if depth <= self.SIMPLE_ALPHA_BETA_DEPTH:
            score = self._alpha_beta_simple(state, depth, current_color, alpha, beta)
            self._search_hash_register(search_key, score, original_alpha, original_beta)
            return score

        moves = self._legal_moves_bits(state, current_color)
        next_color = self._opponent_of(current_color)

        # 現在手番だけ合法手がなければパスし、両者なければ終局として評価する。
        if not moves:
            if not self._legal_moves_bits(state, next_color):
                score = self._terminal_score_for_color_bits(state, current_color)
            else:
                score = -self._negascout(state, depth, next_color, -beta, -alpha, allow_probcut)
            self._search_hash_register(search_key, score, original_alpha, original_beta)
            return score

        # 深く読む前に、浅い評価で枝刈りできるか試す。
        if allow_probcut and depth >= self.PROBCUT_MIN_DEPTH:
            cut_score = self._probcut(state, depth, current_color, alpha, beta)
            if cut_score is not None:
                self._search_hash_register(search_key, cut_score, original_alpha, original_beta)
                return cut_score

        # 良さそうな手から読むことで、alpha-betaの枝刈りを起こしやすくする。
        moves = self._order_move_positions_by_weight(moves)
        if depth >= 2 and len(moves) > 1:
            moves.sort(
                key=lambda move: self._evaluate_for_color_bits(
                    self._apply_move_bits(state, move, current_color), current_color
                ),
                reverse=True,
            )

        search_window = beta
        best_score = float("-inf")

        for index, move in enumerate(moves):
            next_state = self._apply_move_bits(state, move, current_color)
            # 1手目は通常窓、2手目以降は狭い窓で先に読む。
            score = -self._negascout(
                next_state, depth - 1, next_color, -search_window, -alpha, allow_probcut
            )

            # 狭い窓で有望そうなら、通常窓で読み直す。
            if alpha < score < beta and index > 0 and depth > 1:
                score = -self._negascout(
                    next_state, depth - 1, next_color, -beta, -score, allow_probcut
                )

            best_score = max(best_score, score)
            alpha = max(alpha, score)
            if alpha >= beta:
                break
            search_window = alpha + 1

        self._search_hash_register(search_key, best_score, original_alpha, original_beta)
        return best_score

    def _search_hash_key(
        self,
        state: tuple[int, int],
        depth: int,
        current_color: Cell,
        allow_probcut: bool,
    ) -> tuple[int, int, int, int, bool]:
        color_key = 1 if current_color == Cell.BLACK else 2
        black_bits, white_bits = state
        return (black_bits, white_bits, color_key, depth, allow_probcut)

    @classmethod
    def _search_hash_index(cls, key: tuple[int, int, int, int, bool]) -> int:
        black_bits, white_bits, color, depth, allow_probcut = key
        value = black_bits ^ ((white_bits << 1) & cls.FULL_MASK)
        value ^= color * 131 + depth * 17 + int(allow_probcut)
        value = (value ^ (value >> 33) ^ (value >> 17)) & 0xFFFFFFFFFFFFFFFF
        return value & cls.SEARCH_HASH_MASK

    @classmethod
    def _search_hash_get(
        cls,
        key: tuple[int, int, int, int, bool],
        alpha: float,
        beta: float,
    ) -> float | None:
        entry = cls.SEARCH_HASH_TABLE[cls._search_hash_index(key)]
        if entry is None:
            return None
        entry_key, lower, upper = entry
        if entry_key != key:
            return None
        if lower >= beta:
            cls.SEARCH_HASH_GET_COUNT += 1
            return lower
        if upper <= alpha:
            cls.SEARCH_HASH_GET_COUNT += 1
            return upper
        if lower == upper:
            cls.SEARCH_HASH_GET_COUNT += 1
            return lower
        return None

    @classmethod
    def _search_hash_register(
        cls,
        key: tuple[int, int, int, int, bool],
        score: float,
        alpha: float,
        beta: float,
    ) -> None:
        lower = float("-inf")
        upper = float("inf")
        if score <= alpha:
            upper = score
        elif score >= beta:
            lower = score
        else:
            lower = score
            upper = score
        cls.SEARCH_HASH_REG_COUNT += 1
        cls.SEARCH_HASH_TABLE[cls._search_hash_index(key)] = (key, lower, upper)

    def _alpha_beta_simple(
        self,
        state: tuple[int, int],
        depth: int,
        current_color: Cell,
        alpha: float,
        beta: float,
    ) -> float:
        if depth == 0:
            return self._evaluate_for_color_bits(state, current_color)

        moves = self._legal_moves_bits(state, current_color)
        next_color = self._opponent_of(current_color)

        if not moves:
            if not self._legal_moves_bits(state, next_color):
                return self._terminal_score_for_color_bits(state, current_color)
            return -self._alpha_beta_simple(state, depth, next_color, -beta, -alpha)

        best_score = float("-inf")
        for move in moves:
            next_state = self._apply_move_bits(state, move, current_color)
            score = -self._alpha_beta_simple(next_state, depth - 1, next_color, -beta, -alpha)
            best_score = max(best_score, score)
            alpha = max(alpha, score)
            if alpha >= beta:
                break

        return best_score

    def _empty_count_bits(self, state: tuple[int, int]) -> int:
        black_bits, white_bits = state
        return 64 - (black_bits | white_bits).bit_count()

    def _terminal_score_for_color_bits(self, state: tuple[int, int], color: Cell) -> int:
        black_bits, white_bits = state
        black_score = black_bits.bit_count()
        white_score = white_bits.bit_count()
        score = black_score - white_score
        if color == Cell.BLACK:
            return score
        return -score

    def _probcut(self, state: tuple[int, int], depth: int, current_color: Cell, alpha: float, beta: float):
        margin = self.PROBCUT_MARGIN + 0.02 * depth
        estimate = self._evaluate_for_color_bits(state, current_color)
        if estimate >= beta + margin:
            return beta
        if estimate <= alpha - margin:
            return alpha
        if depth < self.PROBCUT_MIN_DEPTH:
            return None

        if depth < len(self.PROBCUT_SHALLOW_DEPTHS):
            probe_depth = self.PROBCUT_SHALLOW_DEPTHS[depth]
        else:
            probe_depth = max(1, depth - 8)
        if probe_depth <= 0:
            return None
        if estimate + margin >= beta:
            high = beta + margin
            high_score = self._negascout(
                state, probe_depth, current_color, high - 0.001, high, allow_probcut=False
            )
            if high_score >= high:
                return beta

        if estimate - margin <= alpha:
            low = alpha - margin
            low_score = self._negascout(
                state, probe_depth, current_color, low, low + 0.001, allow_probcut=False
            )
            if low_score <= low:
                return alpha

        return None

    def _evaluate_for_color_bits(self, state: tuple[int, int], color: Cell) -> float:
        profile_start = self._profile_start()
        score = self._evaluate_black_perspective_bits(state)
        if color == Cell.BLACK:
            result = score
        else:
            result = -score
        self._profile_add("evaluate_for_color", profile_start)
        return result

    def _evaluate_black_perspective_bits(self, state: tuple[int, int]) -> float:
        profile_start = self._profile_start()
        self._eval_count += 1
        cached = type(self).EVAL_CACHE.get(state)
        if cached is not None:
            self._eval_cache_hits += 1
            self._profile_add("evaluate_cache_hit", profile_start)
            return cached
        self._eval_cache_misses += 1
        black_bits, white_bits = state
        pattern_tables = type(self).PATTERN_VALUE_TABLES
        if pattern_tables is None:
            type(self)._precompute_evaluation_tables()
            pattern_tables = type(self).PATTERN_VALUE_TABLES
        final_dense, final_bias = self._params()[2]
        pattern_name_to_final_index = type(self)._pattern_name_to_final_index()
        result = final_bias
        for name in self.ACTIVE_PATTERN_NAMES:
            pattern_specs = self._pattern_bit_specs()[name]
            group_sum = 0.0
            pattern_table = pattern_tables[name]
            for pattern_spec in pattern_specs:
                key_start = self._profile_start()
                key, parts = pattern_spec
                for bit, white_delta, black_delta in parts:
                    if black_bits & bit:
                        key -= black_delta
                    elif white_bits & bit:
                        key -= white_delta
                self._profile_add("pattern_key_bits", key_start)
                value_start = self._profile_start()
                group_sum += pattern_table[key]
                self._profile_add("pattern_value", value_start)
            result += group_sum * final_dense[pattern_name_to_final_index[name]]

        add_key_start = self._profile_start()
        add_key = self._additional_key_bits(state)
        self._profile_add("additional_key_bits", add_key_start)
        add_value_start = self._profile_start()
        add_value = self._add_value(add_key)
        self._profile_add("add_value", add_value_start)
        result += add_value * final_dense[len(self.PATTERN_SIZES)]
        cache = type(self).EVAL_CACHE
        if len(cache) >= self.EVAL_CACHE_MAX_SIZE:
            cache.clear()
        cache[state] = result
        self._profile_add("evaluate_black_perspective", profile_start)
        return result

    @classmethod
    def _pattern_name_to_final_index(cls):
        return {
            "diagonal8": 0,
            "diagonal7": 1,
            "diagonal6": 2,
            "diagonal5": 3,
            "edge": 4,
            "edge2X": 5,
            "triangle": 6,
            "corner3x3": 7,
        }

    @classmethod
    def _params(cls):
        if cls.PARAMS is not None:
            return cls.PARAMS
        if not cls.WEIGHTS:
            raise RuntimeError("exp_020_8patterns.py needs model_8patterns.txt weights before use")

        weights = cls.WEIGHTS
        pos = 0

        def take():
            nonlocal pos
            value = weights[pos]
            pos += 1
            return value

        patterns = {}
        for name, size in cls.PATTERN_SIZES.items():
            dense0 = tuple(tuple(take() for _ in range(size * 2)) for _ in range(16))
            bias0 = tuple(take() for _ in range(16))
            dense1 = tuple(tuple(take() for _ in range(16)) for _ in range(16))
            bias1 = tuple(take() for _ in range(16))
            dense2 = tuple(take() for _ in range(16))
            bias2 = take()
            patterns[name] = (size, dense0, bias0, dense1, bias1, dense2, bias2)

        add_dense0 = tuple(tuple(take() for _ in range(3)) for _ in range(8))
        add_bias0 = tuple(take() for _ in range(8))
        add_dense1 = tuple(take() for _ in range(8))
        add_bias1 = take()
        final_dense = tuple(take() for _ in range(len(cls.PATTERN_SIZES) + 1))
        final_bias = take()
        cls.PARAMS = (patterns, (add_dense0, add_bias0, add_dense1, add_bias1), (final_dense, final_bias))
        return cls.PARAMS

    @classmethod
    def _pattern_value(cls, name: str, key: int) -> float:
        cls._precompute_evaluation_tables()
        return cls.PATTERN_VALUE_TABLES[name][key]

    @classmethod
    def _compute_pattern_value(cls, name: str, key: int) -> float:
        cache_key = (name, key)
        cached = cls.PATTERN_CACHE.get(cache_key)
        if cached is not None:
            return cached

        size, dense0, bias0, dense1, bias1, dense2, bias2 = cls._params()[0][name]
        arr = [0.0] * (size * 2)
        n = key
        for i in range(size - 1, -1, -1):
            digit = n % 3
            n //= 3
            if digit == 0:
                arr[i] = 1.0
            elif digit == 1:
                arr[size + i] = 1.0

        hidden0 = []
        for out_i in range(16):
            value = bias0[out_i]
            row = dense0[out_i]
            for in_i in range(size * 2):
                value += arr[in_i] * row[in_i]
            hidden0.append(cls._leaky_relu(value))

        result = bias2
        for out_i in range(16):
            value = bias1[out_i]
            row = dense1[out_i]
            for in_i in range(16):
                value += hidden0[in_i] * row[in_i]
            result += cls._leaky_relu(value) * dense2[out_i]

        result = cls._leaky_relu(result)
        cls.PATTERN_CACHE[cache_key] = result
        return result

    @classmethod
    def _add_value(cls, key: int) -> float:
        cls._precompute_evaluation_tables()
        return cls.ADD_VALUE_TABLE[key]

    @classmethod
    def _compute_add_value(cls, key: int) -> float:
        cached = cls.ADD_CACHE.get(key)
        if cached is not None:
            return cached

        tmp = key
        sur1 = tmp % 51
        tmp //= 51
        sur0 = tmp % 51
        mobility = tmp // 51 - 30
        arr = (mobility / 30.0, (sur0 - 15.0) / 15.0, (sur1 - 15.0) / 15.0)
        dense0, bias0, dense1, bias1 = cls._params()[1]

        hidden = []
        for out_i in range(8):
            value = bias0[out_i]
            row = dense0[out_i]
            for in_i in range(3):
                value += arr[in_i] * row[in_i]
            hidden.append(cls._leaky_relu(value))

        result = bias1
        for i in range(8):
            result += hidden[i] * dense1[i]
        result = cls._leaky_relu(result)
        cls.ADD_CACHE[key] = result
        return result

    @classmethod
    def _precompute_evaluation_tables(cls) -> None:
        if cls.PATTERN_VALUE_TABLES is not None and cls.ADD_VALUE_TABLE is not None:
            return

        pattern_tables = {}
        for name, size in cls.PATTERN_SIZES.items():
            table_size = 3 ** size
            pattern_tables[name] = tuple(cls._compute_pattern_value(name, key) for key in range(table_size))

        add_table_size = 61 * 51 * 51
        add_table = tuple(cls._compute_add_value(key) for key in range(add_table_size))

        cls.PATTERN_VALUE_TABLES = pattern_tables
        cls.ADD_VALUE_TABLE = add_table
        cls.PATTERN_CACHE = {}
        cls.ADD_CACHE = {}

    @staticmethod
    def _leaky_relu(value: float) -> float:
        if value >= 0.0:
            return value
        return 0.01 * value

    @classmethod
    def _pattern_bit_specs(cls):
        if cls.PATTERN_BIT_SPECS is not None:
            return cls.PATTERN_BIT_SPECS

        specs = {}
        for name, patterns in cls.PATTERN_INDEXES.items():
            group_specs = []
            for pattern in patterns:
                weight = 1
                empty_key = 0
                parts = []
                for index in reversed(pattern):
                    bit = 1 << index
                    empty_key += weight + weight
                    parts.append((bit, weight, weight + weight))
                    weight *= 3
                group_specs.append((empty_key, tuple(parts)))
            specs[name] = tuple(group_specs)
        cls.PATTERN_BIT_SPECS = specs
        return specs

    def _additional_key_bits(self, state: tuple[int, int]) -> int:
        profile_start = self._profile_start()
        cached = type(self).ADDITIONAL_KEY_CACHE.get(state)
        if cached is not None:
            self._profile_add("additional_key_cache_hit", profile_start)
            return cached

        mobility_start = self._profile_start()
        mobility = self._mobility_diff_bits(state)
        self._profile_add("mobility_mask_bits", mobility_start)
        mobility = max(-30, min(30, mobility))
        surround_start = self._profile_start()
        surround_black, surround_white = self._surround_counts_bits(state)
        self._profile_add("surround_counts_bits", surround_start)
        surround_black = max(0, min(50, surround_black))
        surround_white = max(0, min(50, surround_white))
        result = ((mobility + 30) * 51 + surround_black) * 51 + surround_white
        type(self).ADDITIONAL_KEY_CACHE[state] = result
        self._profile_add("additional_key_body", profile_start)
        return result

    def _mobility_diff_bits(self, state: tuple[int, int]) -> int:
        cached = type(self).MOBILITY_CACHE.get(state)
        if cached is not None:
            return cached

        mobility = (
            self._legal_move_mask_bits(state, Cell.BLACK).bit_count()
            - self._legal_move_mask_bits(state, Cell.WHITE).bit_count()
        )
        type(self).MOBILITY_CACHE[state] = mobility
        return mobility

    def _surround_counts_bits(self, state: tuple[int, int]) -> tuple[int, int]:
        profile_start = self._profile_start()
        black_bits, white_bits = state
        occupied = black_bits | white_bits
        empty_bits = self.FULL_MASK ^ occupied
        black_count = 0
        white_count = 0
        for direction in range(8):
            black_count += (empty_bits & self._shift_bits(black_bits, direction)).bit_count()
            white_count += (empty_bits & self._shift_bits(white_bits, direction)).bit_count()
        result = (black_count, white_count)
        self._profile_add("surround_counts_body", profile_start)
        return result

    def _legal_moves_bits(self, state: tuple[int, int], color: Cell) -> tuple[int, ...]:
        profile_start = self._profile_start()
        key = self._legal_moves_cache_key_bits(state, color)
        cached = type(self).LEGAL_MOVES_CACHE.get(key)
        if cached is not None:
            self._legal_moves_cache_hits += 1
            self._profile_add("legal_moves_cache_get", profile_start)
            return cached

        self._legal_moves_cache_misses += 1
        moves = self._timed_legal_moves_bits(state, color)
        self._legal_moves_cache_register(key, moves)
        self._profile_add("legal_moves_cache_get", profile_start)
        return moves

    def _legal_moves_bits_uncached(self, state: tuple[int, int], color: Cell) -> list[int]:
        legal_bits = self._legal_move_mask_bits(state, color)
        moves = []
        bits = legal_bits
        while bits:
            bit = bits & -bits
            moves.append(bit.bit_length() - 1)
            bits ^= bit
        return moves

    def _legal_move_mask_bits(self, state: tuple[int, int], color: Cell) -> int:
        profile_start = self._profile_start()
        key = self._legal_moves_cache_key_bits(state, color)
        cached = type(self).LEGAL_MOVE_MASK_CACHE.get(key)
        if cached is not None:
            self._profile_add("legal_move_mask_cache_get", profile_start)
            return cached

        black_bits, white_bits = state
        occupied = black_bits | white_bits
        empty_bits = self.FULL_MASK ^ occupied
        own_bits = black_bits if color == Cell.BLACK else white_bits
        opponent_bits = white_bits if color == Cell.BLACK else black_bits
        legal_bits = 0

        for direction in range(8):
            candidates = opponent_bits & self._shift_bits(own_bits, direction)
            for _ in range(5):
                candidates |= opponent_bits & self._shift_bits(candidates, direction)
            legal_bits |= empty_bits & self._shift_bits(candidates, direction)

        type(self).LEGAL_MOVE_MASK_CACHE[key] = legal_bits
        self._profile_add("legal_move_mask_cache_get", profile_start)
        return legal_bits

    @classmethod
    def _shift_bits(cls, bits: int, direction: int) -> int:
        if direction == 0:  # north-west
            return ((bits & cls.NOT_A_FILE) >> 9) & cls.FULL_MASK
        if direction == 1:  # north
            return (bits >> 8) & cls.FULL_MASK
        if direction == 2:  # north-east
            return ((bits & cls.NOT_H_FILE) >> 7) & cls.FULL_MASK
        if direction == 3:  # west
            return ((bits & cls.NOT_A_FILE) >> 1) & cls.FULL_MASK
        if direction == 4:  # east
            return ((bits & cls.NOT_H_FILE) << 1) & cls.FULL_MASK
        if direction == 5:  # south-west
            return ((bits & cls.NOT_A_FILE) << 7) & cls.FULL_MASK
        if direction == 6:  # south
            return (bits << 8) & cls.FULL_MASK
        return ((bits & cls.NOT_H_FILE) << 9) & cls.FULL_MASK

    def _legal_moves_cache_key_bits(self, state: tuple[int, int], color: Cell) -> tuple[int, int, int]:
        color_key = 1 if color == Cell.BLACK else 2
        black_bits, white_bits = state
        return (black_bits, white_bits, color_key)

    @classmethod
    def _legal_moves_cache_register(
        cls,
        key: tuple[int, int, int],
        moves: tuple[int, ...] | list[int],
    ) -> None:
        if key not in cls.LEGAL_MOVES_CACHE and len(cls.LEGAL_MOVES_CACHE) >= cls.LEGAL_MOVES_CACHE_MAX_SIZE:
            cls.LEGAL_MOVES_CACHE.pop(next(iter(cls.LEGAL_MOVES_CACHE)))
        cls.LEGAL_MOVES_CACHE[key] = tuple(moves)

    def _apply_move_bits(self, state: tuple[int, int], move: int, color: Cell) -> tuple[int, int]:
        profile_start = self._profile_start()
        black_bits, white_bits = state
        move_bit = 1 << move
        flips_start = self._profile_start()
        flips = self._flips_bits(state, move, color)
        self._profile_add("flips_bits", flips_start)
        if color == Cell.BLACK:
            black_bits |= move_bit | flips
            white_bits &= ~flips
        else:
            white_bits |= move_bit | flips
            black_bits &= ~flips
        result = (black_bits & self.FULL_MASK, white_bits & self.FULL_MASK)
        self._profile_add("apply_move_bits", profile_start)
        return result

    def _flips_bits(self, state: tuple[int, int], move: int, color: Cell) -> int:
        profile_start = self._profile_start()
        black_bits, white_bits = state
        move_bit = 1 << move
        if (black_bits | white_bits) & move_bit:
            self._profile_add("flips_bits_body", profile_start)
            return 0
        own_bits = black_bits if color == Cell.BLACK else white_bits
        opponent_bits = white_bits if color == Cell.BLACK else black_bits
        row = move // 8
        col = move % 8
        flips = 0
        for delta_row, delta_col in self.DIRECTIONS:
            r = row + delta_row
            c = col + delta_col
            direction_flips = 0
            while 0 <= r < 8 and 0 <= c < 8:
                bit = 1 << (r * 8 + c)
                if opponent_bits & bit:
                    direction_flips |= bit
                    r += delta_row
                    c += delta_col
                    continue
                if own_bits & bit:
                    flips |= direction_flips
                break
        self._profile_add("flips_bits_body", profile_start)
        return flips

    @classmethod
    def _book_cache(cls):
        if cls.BOOK_CACHE is not None:
            return cls.BOOK_CACHE

        cache = {}
        for line in cls.BOOK_LINES:
            prefix = line[:-2]
            move_text = line[-2:]
            for transform in range(4):
                board = cls._initial_board()
                current_color = Cell.BLACK
                for i in range(0, len(prefix), 2):
                    move = cls._coord_to_move(prefix[i:i + 2], transform)
                    board = cls._apply_move_for_color(board, move, current_color)
                    current_color = Cell.WHITE if current_color == Cell.BLACK else Cell.BLACK
                cache[(cls._board_key(board), current_color)] = cls._coord_to_move(move_text, transform)

        cls.BOOK_CACHE = cache
        return cache

    def _book_move_bits(self, state: tuple[int, int]) -> Move:
        return self._book_cache().get((self._board_key_bits(state), self.color))

    @staticmethod
    def _initial_board() -> Board:
        board = [[Cell.EMPTY for _ in range(8)] for _ in range(8)]
        board[3][3] = Cell.WHITE
        board[3][4] = Cell.BLACK
        board[4][3] = Cell.BLACK
        board[4][4] = Cell.WHITE
        return board

    @staticmethod
    def _coord_to_move(coord: str, transform: int) -> Move:
        col = ord(coord[0]) - ord("a")
        row = int(coord[1]) - 1
        if transform == 0:
            return (row, col)
        if transform == 1:
            return (col, row)
        if transform == 2:
            return (7 - row, 7 - col)
        return (7 - col, 7 - row)

    @classmethod
    def _apply_move_for_color(cls, board: Board, move: Move, color: Cell) -> Board:
        row, col = move
        next_board = [board_row[:] for board_row in board]
        next_board[row][col] = color
        opponent_color = Cell.WHITE if color == Cell.BLACK else Cell.BLACK

        for delta_row, delta_col in cls.DIRECTIONS:
            direction_flips = []
            current_row = row + delta_row
            current_col = col + delta_col
            while (
                0 <= current_row < 8
                and 0 <= current_col < 8
                and board[current_row][current_col] == opponent_color
            ):
                direction_flips.append((current_row, current_col))
                current_row += delta_row
                current_col += delta_col

            if (
                direction_flips
                and 0 <= current_row < 8
                and 0 <= current_col < 8
                and board[current_row][current_col] == color
            ):
                for flip_row, flip_col in direction_flips:
                    next_board[flip_row][flip_col] = color

        return next_board

    @staticmethod
    def _board_key(board: Board) -> tuple[int, ...]:
        values = []
        for row in board:
            for cell in row:
                if cell == Cell.BLACK:
                    values.append(1)
                elif cell == Cell.WHITE:
                    values.append(2)
                else:
                    values.append(0)
        return tuple(values)

    @staticmethod
    def _board_key_bits(state: tuple[int, int]) -> tuple[int, ...]:
        black_bits, white_bits = state
        values = []
        for pos in range(64):
            bit = 1 << pos
            if black_bits & bit:
                values.append(1)
            elif white_bits & bit:
                values.append(2)
            else:
                values.append(0)
        return tuple(values)

    @staticmethod
    def _board_to_bits(board: Board) -> tuple[int, int]:
        black_bits = 0
        white_bits = 0
        for row in range(8):
            for col in range(8):
                bit = 1 << (row * 8 + col)
                cell = board[row][col]
                if cell == Cell.BLACK:
                    black_bits |= bit
                elif cell == Cell.WHITE:
                    white_bits |= bit
        return black_bits, white_bits

    @staticmethod
    def _move_to_pos(move: Move) -> int:
        row, col = move
        return row * 8 + col

    @staticmethod
    def _pos_to_move(pos: int) -> Move:
        return (pos // 8, pos % 8)

    def _opponent_of(self, color: Cell) -> Cell:
        if color == self.color:
            return self.opponent_color
        if color == self.opponent_color:
            return self.color
        return Cell.WHITE if color == Cell.BLACK else Cell.BLACK
